  _ = `Buntsamarbeid`,
  v = `Valgfritt: Du kan velge å invitere andre utviklere til å inkludere sine spill i bunten din. Som eieren av bunten, er du ansvarlig for å koordinere med de andre utviklerne. Som eier er du også den eneste som kan publisere bunten til Steam-butikken. Hver gang en pakke blir lagt til bunten, eller når rabattprosenten endres, må alle samarbeidspartnere godkjenne at deres spill er inkludert i bunten før den kan publiseres.`,
