  w = `Dashbord for salgssider`,
  T = `Begivenhetssider for salgskampanjer`,
  E = `Her finner du salgssidene på Steam som inneholder ett eller flere spill som du har administrasjonsrettigheter til. Noen ganger er disse sidene satt opp av arrangører, og noen ganger av Valve som del av en salgskampanje.`,
  D = `Dette er alle de aktive og klargjorte salgssidene, skapt enten av Valve eller en godkjent tredjepart. %1$s for å legge til en ny partner slik at de kan skape sin egen salgsside. Du kan henvise partneren din til %2$s.`,
