  H = `Salget varer til`,
  U = `Inkluderte spill (hurtigvisning)`,
  W = `Dette er en liste over spillene dine som er med på begivenheten.`,
  G = `Bla gjennom`,
  K = `Denne begivenheten er skjult, og du har ikke redigeringstilgang. Noen på teamet ditt har derimot det. For å finne personen på teamet ditt med tillatelse til å redigere denne begivenheten, hold musepekeren over gruppeikonet nedenfor og trykk på «Se medlemsliste». Medlemmene i laget med statusen «Offiser» har redigeringsrettigheter for denne begivenheten.`,
  q = `Denne begivenheten er ikke synlig enda, men vi viser den til deg fordi du har et spill oppført på salgssiden. Hvis dette ikke er som ventet, ta kontakt med arrangørene av salget.`,
