  st = `Skriv inn gruppenavn eller nettadresse for butikkside`,
  ct = `Salgsbegivenheten må opprettes på en skaperside (dvs. utvikler-/utgiver-/serieside). Søk etter navnet på skapersiden nedenfor:`,
  lt = `Skriv inn enten navnet på gruppen tilknyttet en skaperside eller butikkens nettadresse dersom dette er for en kurator eller nylig opprettet samfunnsgruppe.`,
  ut = `1. Valgt skaper til å arrangere salgsbegivenheten:`,
  dt = `Fjern skaper og søk på nytt etter en annen skaperside`,
  ft = `2. Bekreft at skapersiden har partnerbegivenheter slått på:`,
  pt = `Denne skapersiden må bli med i partnerbegivenheter-betaen for å bruke salgsfunksjonen. Denne handlingen kan ikke omgjøres. Dette endrer redigeringsfunksjonen hvor de legger ut kunngjøringer, og det forhindrer dem i å opprette lenkede kunngjøringer. %1$s`,
  mt = `3. Angi påkrevd informasjon:`,
  ht = `Beskrivende begivenhetsnavn`,
  gt = `Dette er det lange begivenhetsnavnet som vises for brukere. Det kan inkludere partner og begivenhetsdatoer.`,
