  ks = `Angi en beskrivelse og tittel på minst ett språk`,
  As = `Endringsloggen må også ha en engelsk tittel og beskrivelse`,
  js = `Tittelen for %1$s er for lang`,
  Ms = `Beskrivelsen for %1$s er for lang`,
  Ns = `%1$s har en beskrivelse, men ingen tittel`,
  Ps = `%1$s har en tittel, men ingen beskrivelse`,
  Fs = `Legger ut liten oppdatering`,
  Is = `Kunne ikke legge ut denne lille oppdateringen. Du kan gå tilbake til redigeringsverktøyet og prøve å sende inn denne begivenheten igjen, eller prøve å legge ut gjennom det fullstendige redigeringsverktøyet.`,
  Ls = `Tilbake til redigeringsverktøyet`,
