  D_ = `Hvis spillet installerer antijuks i kjernemodus på klientsiden, må du erklære dette til brukere her. Hvis du har en egen løsning for antijuks eller løsningen du bruker ikke finnes på listen nedenfor, velg «Annet» og angi egen informasjon.`,
