  iv = `Forklar utgavene …`,
  av = `Dette grensesnittet lar deg velge et bilde som beskriver forskjellen mellom utgavene til spillet (f.eks. standard vs. deluxe vs. årets spill osv.). Utgaver grupperes sammen med hovedspillet øverst i kjøpsalternativene og sorteres fra lavest til høyest pris på butikksiden. Se <1>dokumentasjonen om behandling av utgaver</1> for mer informasjon.`,
