  fb = `Dette legger til kapseldesign til pakkens kjøpsvisning i butikken, på samme måte som innhold i bunter vises. Hovedapplikasjonen vises først, og så andre inkluderte applikasjoner, fra høyest til lavest pris.`,
  pb = `Utelat spillnavnet fra begynnelsen av gjenstander på listen over pakkens innhold.`,
  mb = `For å redusere overflødige ord og øke lesbarhet kan du utelate spillnavnet pluss blanktegn og tilhørende tegn, som kolon eller bindestreker, fra starten av gjenstander som nedlastbart innhold og lydspor når de er oppført i pakkens kjøpsområde. For eksempel vises «Half Life 2: Episode 1» som «Episode 1». Skjuler kun det nøyaktige navnet til hovedspillet pluss blanktegn og vanlige skilletegn som bindestreker og kolon.`,
