  vF = `Ingen forhåndsbehandling`,
  yF = `Komprimer tabell`,
  bF = `Autonormalisering`,
  xF = `Serienormalisering`,
  SF = `Normaliserer all data innenfor den angitte min/maks-serien til 0–1-serien, og begrenser alle verdiene utenfor serien.`,
  CF = `Minste verdi`,
  wF = `Maks verdi`,
  TF = `Standardavvik`,
  EF = `Utvid`,
  DF = `Minimer`,
  OF = `Slett node`,
  kF = `Bredde`,
  AF = `Kommentar`,
  jF = `En valgfri kommentar som beskriver hva denne noden brukes til.`,
  MF = `Inndata`,
  NF = `Komprimert tabell`,
  PF = `Det komprimerte navnet som dataene med hull refererer til.`,
  FF = `Antall inndata`,
  IF = `Bredde`,
  LF = `Antall inndata`,
  RF = `Antall inndata som det skal trekkes ut korresponderende elementer fra. For å trekke ut app-ID må første inndata være listen over app-ID-er.`,
  zF = `Hent %1$s`,
  BF = `Tren %1$s`,
  VF = `– (kommer snart)`,
  HF = `– (gratis)`,
  UF = `Offisiell rabattbegivenhet`,
  WF = `Rabatt planlagt`,
  GF = `Trinn %1$s`,
  KF = `Generell inndatastøtte`,
  qF = `For å gi en så god beskrivelse av spillets grad av kontrollerstøtte til spillere som mulig har vi en liten veiviser med noen raske spørsmål. Gå gjennom denne veiviseren og svar så godt du kan på spørsmålene, slik at Steam kan sette spillere i forbindelse med spill som fungerer bra med enhetene de har.`,
  JF = `Vær oppmerksom på at alle de støttede VR-enhetene, deriblant inndataenheter, bør beskrives i systemkravene. Kontrollerstøtten som er beskrevet her, bør henvise til støtten for skrivebordet eller Big Picture-modus. `,
  YF = `Hva slags enheter kan brukes til å spille spillet knirkefritt?`,
  XF = `Kun mus og tastatur`,
  ZF = `Mus og tastatur, samt spillkontroller`,
  QF = `Mus og tastatur, men spillkontroller foretrekkes`,
  $F = `Spillkontroller kreves – ingen støtte for mus og tastatur`,
  eI = `Ja, spillet oppfyller vilkårene ovenfor for full støtte`,
  tI = `Nei, spillet oppfyller ikke alle vilkårene ovenfor`,
  nI = `DualShock-kontroller (USB)`,
  rI = `DualShock-kontroller (USB + Bluetooth)`,
  iI = `DualSense-kontroller (USB)`,
  aI = `DualSense-kontroller (USB + Bluetooth)`,
  oI = `Nei, spillet støtter ikke noen PlayStation-kontrollere`,
  sI = `Ja, spillet har full integrasjon med Steam Input-API-et`,
  cI = `Nei, spillet gjør ikke nytte av Steam Input-API-et`,
  lI = `Støtte for Xbox-kontrollere`,
  uI = `Hvis spillet har full støtte for Xbox-kontrollere, er det mulig for en spiller å starte, konfigurere, spille og avslutte spillet uten å ha tilgang til et tastatur. For å oppriktig gi uttrykk for at spillet har full støtte for Xbox-kontrollere, må spillet kunne gjøre følgende:`,
  dI = `En spiller må kunne utføre alt i spillet med kun en kontroller. Dette gjelder også å navigere seg gjennom startprogram før spillet starter, spille spillet, bruke menyer, endre innstillinger og avslutte spillet.`,
  fI = `Når kontrolleren kobles fra, må spillet settes på pause, med mindre det er et flerspillerspill.`,
  pI = `Eventuelle felt for tekstinndata må åpne et virtuelt tastatur på skjermen.`,
  mI = `Hvis spillet støtter lokal flerspiller, må den modusen fungere med flere kontrollere.`,
  hI = `Oppfyller spillet vilkårene ovenfor for full støtte av Xbox-kontrollere?`,
  gI = `Støtte for PlayStation-kontrollere`,
  _I = `Hvis spillet har støtte for én eller flere PlayStation-kontrollere oppført nedenfor, bør det generelt sett være mulig å bruke de enhetene til å gjøre alt i spillet som kan gjøres med Xbox-kontrollere. I tillegg må spillet gjøre det følgende for å bli ansett som å støtte PlayStation-kontrollere:`,
  vI = `Vise riktige symboler (ikoner) på skjermen når brukeren blir bedt om å trykke på en bestemt knapp.`,
  yI = `Spille spillet, bruke menyene, endre innstillinger og avslutte.`,
  bI = `<1>Merknad om USB/Bluetooth:</1> For PlayStation-kontrollere på PC er det vanlig at USB-forbindelser fungerer bra, men at de ikke har samme grad av støtte når tilkoblet via Bluetooth. Fint om du bekrefter med det tekniske teamet at spillet faktisk fungerer med Bluetooth før du velger disse nedenfor.`,
  xI = `<1>Ja</1>, spillet støtter: (velg alle som gjelder)`,
  SI = `Integrasjon med Steam Input-API-et`,
  CI = `Hvis spillet har fullstendig integrasjon med Steam Input-API-et, skal det fungere med omtrent alle 200+ kontrollermodellene som en spiller kobler til, deriblant fremtidige modeller. For å oppriktig gi uttrykk for at spillet har denne støtten, må det i det minste kunne gjøre følgende:`,
  wI = `Implementere handlinger i Steam Input-API-et og spørre etter tilhørende handlingsopprinnelse for å kunne vise riktige kontrollersymboler i spillet for de vanligste kontrollermodellene.`,
  TI = `Automatisk sette på pause hvis kontrolleren kobles fra.`,
