  QL = `Mer fra (serie/utvikler/utgiver)`,
  $L = `Det finnes ingen skapersider for applikasjonen din. Gå gjennom dokumentasjonen om skapersider for <1>utviklersider/utgiversider</1> eller for <2>seriesider</2> for å sette disse opp for applikasjonen din.`,
