  SR = `Ikke angitt. Butikken velger som standard skaperens første serieside som er knyttet til spillet (dersom den finnes).`,
  CR = `<Inkluder fra alle kilder>`,
  wR = `Inkluder alle spill fra alle skapersider (utvikler/utgiver/serie) knyttet til dette spillet. Manuell fremheving gjør det mulig å velge spesifikke skapersider å rette fokus på. Algoritmisk fremheving velger først tilknyttet skaper i rekkefølgen serie, utvikler og utgiver for visning.`,
  TR = `Nødvendig nedlastbart innhold`,
  ER = `Krever dette nedlastbare innholdet et annet nedlastbart innhold for å fungere? Velg nødvendige nedlastbare innhold å vise som påkrevd. Butikken viser automatisk denne avhengigheten, sammen med et alternativ for å kjøpe alle avhengige produkter sammen.`,
  DR = `Legg til som avhengighet`,
  OR = `Forholdet til avhengigheten`,
  kR = `Påkrevd`,
  AR = `Nedlastbart innhold som er nødvendig for at dette nedlastbare innholdet skal fungere ordentlig.`,
  jR = `Anbefalt`,
