  NR = `Oversikt`,
  PR = `Design`,
  FR = `Utgivelse`,
  IR = `Beskrivelse av sesongpassets fremdriftsplan`,
  LR = `Sesongpass er nedlastbart innhold som kan kjøpes med et løfte om at fremtidig innhold leveres til disse kundene, enten som separate utgivelser av nedlastbart innhold eller som tilleggsinnhold som låses opp i hovedspillet.`,
  RR = `Hvis utviklere vil forplikte seg til dette, må de beskrive hver av de viktigste datoene for levering av innhold og selve innholdet til spillere ved å angi hver dato og alt innhold nedenfor.`,
  zR = `Bruk den generelle seksjonen «Om dette produktet» ovenfor for å gi en generell beskrivelse av sesongpasset, mens du bruker innholdsleveringsdatoene nedenfor for enkelte innholdsutgivelser.`,
  BR = `Når du er klar til fortelle spillere at du har gitt ut innhold i sesongpasset, kan du bruke alternativet «Marker som utgitt» nedenfor og følge instruksjonene. Gå gjennom <1>utgivelsesdokumentasjonen for sesongpass</1> for mer informasjon.`,
  VR = `Opprett ny innholdsutgivelse`,
  HR = `Innholdsutgivelse er noe spesifikt som leveres og som kunder kan forstå, med en forventet dato for levering.`,
  UR = `Opprett ny innholdsutgivelse`,
  WR = `Beskriv sesongpassets innholdsutgivelse til spillere.`,
