  ZR = `Utgivelsesdato`,
  QR = `Når fikk kunder først tilgang til dette innholdet`,
  $R = `Marker som tidligere utgitt`,
  ez = `Dette er innhold som ble utgitt tidligere. Hvis dette velges, kan datoen angis til fortiden. Når dette publiseres, får kunder ikke varsel om utgivelsen. Valget kan ikke fjernes hvis datoen er i fortiden.`,
  tz = `Kan ikke fjerne tidligere utgitt uten å først flytte utgivelsesdato til fremtiden.`,
