  dz = `Bruker`,
  fz = `Offentlig synlig utgivelsesdato`,
  pz = `Du kan velge å vise en vagere dato til spillere hvis du er usikker på den nøyaktige utgivelsesdatoen for dette innholdet.`,
  mz = `Tittel på innholdsutgivelse (offentlig)`,
  hz = `Hva kalles dette innholdet?`,
  gz = `Beskrivelse av innholdsutgivelse (offentlig)`,
  _z = `Fortell spillere om innholdet i denne utgivelsen her. Dette kan være så kort eller langt som du vil. Hvis du har tenkt å gi ut dette innholdet som nedlastbart innhold, kan beskrivelsen her være den samme som på siden til det nedlastbare innholdet.`,
