  qz = `Kommer:`,
  Jz = `Tilknytning mangler`,
  Yz = `Milepælen er allerede utgitt. Det er fortsatt mulig å tilknytte nedlastbart innhold eller utgivelsesbegivenhet. Dette oppdaterer simpelthen visningen uten å endre milepælens utgivelsesdato.`,
  Xz = `Tilknytning etter utgivelse av milepæl`,
  Zz = `Milepælen er allerede markert som utgitt til kunder. Dette kan brukes for å tilknytte manglende nedlastbart innhold og utgivelsesbegivenhet. Dette oppdaterer simpelthen visningen når det publiseres.`,
  Qz = `Undersøkelse om Steam-teamets bransjemøter`,
  $z = `Hei, %1$s! %2$s Hvor har du lyst til å møte oss?`,
  eB = `Nedenfor finner du begivenheter som medlemmer av Steam-teamet vurderer å delta på. Hvis du også vurderer å delta, eller bor i nærheten og kan møte oss, kan du gi oss beskjed i skjemaet nedenfor. Vi kommer til å bruke dette for å planlegge reiser og begivenheter. Hvis du melder deg på en begivenhet som vi vurderer å delta på, kommer vi til å prioritere de som deltar, før vi sender ut en videre invitasjon.`,
  tB = `Om deg`,
  nB = `Gi oss beskjed om hvem du er og hvordan vi får tak i deg:`,
  rB = `E-postadresse`,
  iB = `Adresse mangler`,
  aB = `Oppdater e-postadresse?`,
  oB = `Dette bruker e-postadressen registrert i partnerkontoen din som standard. Du kan oppdatere den om du vil at kommunikasjon om begivenheter skal sendes til en annen adresse.`,
  sB = `Bedrift`,
  cB = `Hvor skal du?`,
  lB = `Fortell oss hvilke spillbransjebegivenheter du har tenkt å bli med på i %1$s.`,
  uB = `Angir hvilke begivenheter som medlemmer av Steam-teamet har planer om å delta på. Alle andre er begivenheter vi fremdeles vurderer.`,
  dB = `Kryss av for begivenheter du har planer om å delta på, selv om deltakelsen ikke er bekreftet enda.`,
  fB = `Hvilke andre begivenheter har du planer om å delta på som vi ikke fikk med ovenfor?`,
  pB = `Konferanseundersøkelsen er lukket for øyeblikket.`,
  mB = `Har vi møtt deg før personlig?`,
  hB = `Nei, jeg har aldri møtt et medlem av Steam-teamet personlig`,
  gB = `Føler du deg komfortabel med å delta på et foredrag eller en begivenhet som hovedsakelig eller fullstendig foregår på engelsk?`,
  _B = `Ja, jeg føler meg komfortabel med engelsk som hovedspråk.`,
  vB = `Nei, jeg trenger hjelp med oversettelse.`,
  yB = `Hvilket språk foretrekker du?`,
  bB = `Dette er for å hjelpe oss med å avgjøre om det er behov for tolk når vi avholder et slikt arrangement.`,
  xB = `Undersøkelse om Meet Steam: %1$s`,
  SB = `Har du tilbakemelding på noen av Steam-øktene du deltok i på Valves plass i Convene? Denne undersøkelsen har virkelig bare ett spørsmål. Vi er ute etter å forstå om noe stakk seg ut i tankene dine om innhold, kvalitet, timing, sted eller innhold i øktene, om dette er bra eller dårlig.`,
  CB = `Tidligere arrangement: (%1$s)`,
  wB = `Konferansearrangører vil gjerne vite om du planlegger å delta og om du er interessert i å møte medlemmer fra Steam.`,
  TB = `Andre konferanser`,
  EB = `Velg bunt som skal festes`,
  DB = `Ingen bunter festet.`,
  OB = `Ingen alternativer`,
  kB = `Dra de nødvendige ressursene hit (maks 50 MB)`,
  AB = `Enten er størrelsen er feil, eller så støttes ikke filtypen.`,
  jB = `Duplisert %1$s. Fjern ressursen du ikke vil fortsette med.`,
  MB = `Det oppstod et problem under opplasting av denne filen. Prøv igjen.`,
  NB = `Nødvendige ressurser mangler.`,
  PB = `Oppstartsvideo`,
  FB = `Forhåndsvisningsbilde`,
  IB = `Retningslinjer for video`,
  LB = `Oppstartsvideoer må ha en størrelse på 1920 x 1200 piksler for visning i full skjerm på Steam Deck. Man bør ta i betraktning at disse beskjæres til 1920 x 1080 piksler på de fleste skjermer i Big Picture-modus.`,
  RB = `De bør være mellom 3 og 10 sekunder lange.`,
  zB = `De kan inneholde spillets logo, men ingen annen tekst eller markedsføringsmaterialer er tillatt.`,
  BB = `Kan ikke inneholde gjennomsiktighet. Du må kanskje slå av alfakanalen under eksport.`,
  VB = `Endelig fil må være i formatet .webm eller .mp4, og kan ikke være større enn 50 MB. Den komprimeres til en rimelig filstørrelse.`,
  HB = `Retningslinjer for lyd`,
  UB = `Alle oppstartsvideoer kan inneholde lyd i tillegg til video. Lyden bør være designet for å fungere bra med høyttalerne til Steam Deck, og den bør ikke være så høy at den overvelder brukere ved oppstart.`,
  WB = `Lydfiler bør være i 16-biter og 48 kHz.`,
  GB = `Endelig utdata bør ha et toppnivå på -12 dB og gjennomsnittlig volum på -14 LUFS. Vi normaliserer lyden slik at lyden ikke er for høy.`,
  KB = `Unngå for mye mellom- til lavfrekvenser og vurder en HPF som starter rundt 40–80 Hz. `,
  qB = `Vurder å tone lydfilen inn og ut i henholdsvis begynnelsen og slutten for å unngå eventuelle klikk eller skarpe kutt på slutten av oppstartsvideoen.`,
  JB = `Retningslinjer for forhåndsvisningsbilde`,
  YB = `Oppgi et stillbilde på 1920 x 1200 piksler fra oppstartsvideoen. Dette bildet brukes til å representere oppstartsvideoen i en brukers lager.`,
  XB = `jpeg, png og webp er godtatt.`,
  ZB = `Kan ikke inneholde gjennomsiktighet.`,
  QB = `Ingen animasjon – det må være et enkelt bilde.`,
  $B = `Tilknyttet %1$s`,
  eV = `Navnet kan ikke endres mens det er tilknyttet en skaperside. Du må oppheve tilknytningen først hvis du må endre.`,
  tV = `Opphev tilknytningen mellom «%1$s» og «%2$s» for dette spillet. Dette trer i kraft umiddelbart.`,
  nV = `* Krever lagring`,
  rV = `Seriesiden kan ikke være den samme som utvikler- eller utgiversiden.`,
  iV = `Denne gruppen er allerede lenket til en utgiver med et annet navn. Se instruksjoner til høyre.`,
  aV = `Denne gruppen er tilknyttet som en utvikler eller utgiver på en annen applikasjon, så butikken kommer ikke til å vise den som en serie. Tilknytt heller en gruppe som kun brukes til serien.`,
  oV = `Lenket som en utvikler eller utgiver på:`,
  sV = `(%1$s til)`,
  cV = `Butikken lenker en serie til startsiden når minst to spill i butikken lenker til den som sin serie. Nedlastbart innhold, demoer og programvare teller ikke. Inntil da vises serienavnet uten en lenke.`,
  lV = `Velg en skaperside`,
  uV = `Knytt «%1$s» til en startside`,
  dV = `Velg en eksisterende skaperside eller samfunnsgruppe som skal knyttes til «%1$s» for dette spillet.`,
  fV = `Dette er en eksisterende skaperside og er knyttet til et annet spill for denne partnerkontoen.`,
