  Eq = `Prestasjoner som ikke samsvarer med et eksisterende API-navn, er oppført her. De tildeles en ny prestasjons-ID. Hvis du egentlig ville endre et eksisterende API-navn, må du redigere det i redigeringsverktøyet først.`,
  Dq = `Mangler fra CSV (%1$s)`,
  Oq = `Prestasjoner som tidligere er definerte, men som ikke ble funnet i den importerte CSV-filen, er oppført her. Disse blir værende med mindre du krysser av boksen nedenfor for å slette dem.`,
  kq = `Slett disse prestasjonene`,
  Aq = `Endres (%1$s)`,
  jq = `Prestasjoner som er blitt endret, er oppført her. Disse blir oppdatert.`,
  Mq = `Uendret (%1$s)`,
  Nq = `Uendrede prestasjoner er oppført her. Disse oppdateres ikke.`,
  Pq = `Mangler prestasjonsbilde`,
  Fq = `Ugyldig csv: Tillagte prestasjoner må alle referere til statistikker i et enkelt sett (eller i standardsettet).`,
  Iq = `Ugyldig API-navn: Navn må være unike.`,
  Lq = `Feil oppdaget i importert csv-fil. Rett opp feilene nedenfor, og last opp filen på nytt.`,
  Rq = `Indikerer endring`,
  zq = `Sett-ID`,
  Bq = `Sett som har fått endret navn, er oppført her. Disse blir oppdatert.`,
  Vq = `Uendrede sett er oppført her. Disse oppdateres ikke.`,
  Hq = `Ugyldig sett-ID: Sett-ID-er må være unike.`,
  Uq = `Ugyldig sett-ID: Prestasjonssettet til kjernespillet kan ikke få nytt navn.`,
  Wq = `Uventet kolonne: «%1$s» er ikke et støttet språk.`,
  Gq = `Ugyldig navn: Sett må ha et engelsk navn.`,
  Kq = `Ugyldig statistikknavn: Statistikken finnes ikke. <1>Rediger statistikk</1> først for å opprette nye.`,
  qq = `Ugyldig tillatelse: Prestasjon og statistikk må ha samme tillatelse.`,
  Jq = `Ugyldig heltall: Verdien må være et heltall når statistikken er heltall (integer).`,
  Yq = `Ugyldig fremdriftsområde: Maksimum må være større enn minimum.`,
  Xq = `Ugyldig fremdriftsminimum: Minimum fremdrift må være større enn eller lik statistikkens minimum.`,
  Zq = `Ugyldig sett-ID: Sett-ID-en eksisterer ikke.`,
  Qq = `Omorganiser sett`,
  $q = `Dra og slipp prestasjonssett for å angi visningsrekkefølgen for brukere`,
  eJ = `Kan ikke flytte standardsett`,
  tJ = `Innstillinger`,
  nJ = `Bildets bredde og høyde må være lik`,
  rJ = `Bildestørrelsen må være minst %1$s x %1$s`,
  iJ = `Ukjent innholdstype`,
  aJ = `Fant ingen prestasjoner med API-navnet «%1$s» – kan ikke tilordne bilde.`,
  oJ = `Prestasjonen «%1$s» mangler i den opplastede CSV-definisjonsfilen, så dette ikonet blir ikke tildelt. Legg den til i CSV-filen, eller fjern CSV-filen for å laste opp ikoner for seg selv.`,
  sJ = `Denne prestasjonen mangler i den opplastede CSV-definisjonsfilen, så lokaliseringen dens blir ikke oppdatert. Legg den til i CSV-definisjonsfilen, eller fjern lokaliseringsstrengene for den fra denne filen.`,
  cJ = `Fant ingen prestasjon med dette API-navnet, så lokaliseringen dens blir ikke oppdatert. API-navn skiller mellom store og små bokstaver her.`,
